package com.companages.controller;
import com.companages.dto.AssignmentDtos.*; import com.companages.service.AssignmentService; import jakarta.validation.Valid; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import java.util.List;
@RestController @RequestMapping("/api/organizations/{organizationId}/assignments") public class AssignmentController { private final AssignmentService service; public AssignmentController(AssignmentService s){service=s;} @PostMapping ResponseEntity<Response> create(@PathVariable Long organizationId,@Valid @RequestBody CreateRequest r){return ResponseEntity.status(HttpStatus.CREATED).body(service.create(organizationId,r));} @GetMapping List<Response> list(@PathVariable Long organizationId){return service.list(organizationId);} @DeleteMapping("/{id}") @ResponseStatus(HttpStatus.NO_CONTENT) void delete(@PathVariable Long organizationId,@PathVariable Long id){service.delete(organizationId,id);} }
